const rows = $input.all();

const emails = new Set();

let duplicateEmails = [];
let duplicateFeedback = [];
let invalidRatings = [];

for (const item of rows) {

    const email = item.json.email;

    if (email) {
        if (emails.has(email)) {
            duplicateEmails.push(email);
        } else {
            emails.add(email);
        }
    }

    if (item.json.rating !== undefined && item.json.rating !== "") {
        const rating = Number(item.json.rating);

        if (rating < 1 || rating > 5) {
            invalidRatings.push(email);
        }
    }
}

const issuesFound =
    duplicateEmails.length > 0 ||
    invalidRatings.length > 0;

const alertType = issuesFound
    ? "Issues Found"
    : "No Issues";

const details = issuesFound
    ? `Duplicate Emails: ${
        duplicateEmails.length ? duplicateEmails.join(", ") : "None"
      } | Invalid Ratings: ${
        invalidRatings.length ? invalidRatings.join(", ") : "None"
      }`
    : "Audit completed successfully. No anomalies detected.";

return [{
    json: {
        issuesFound,
        timestamp: new Date().toISOString(),
        workflowName: "Event Feedback Audit",
        alertType,
        details,
        duplicateEmails,
        invalidRatings
    }
}];

const participants = $('Get Participants').all();
const feedback = $('Get Feedback').all();

const totalRegistered = participants.length;
const totalAttended = participants.filter(p => p.json.attendance === true || p.json.attendance === 'true').length;
const avgRating = feedback.length 
  ? (feedback.reduce((sum, f) => sum + Number(f.json.rating), 0) / feedback.length).toFixed(1)
  : 0;

return [{ json: { totalRegistered, totalAttended, avgRating } }];
